import Testing
@testable import SpiceCodecs
import SpiceWire

struct CubicStrokeTests {
    private let visible = Rect(x: -20, y: -20, width: 40, height: 40)

    @Test func safePinnedReferenceCurvesProduceTheSameRoundedEndpoints() throws {
        // Independently generated by a bounded C oracle from spice-common
        // 58d375e5eadc6fb9e587e99fd81adcb95d01e8d6. Values are fixtures, not code.
        let fixtures: [(Point, [StrokePoint], [Point])] = [
            (.init(x: 0, y: 0), [p(0, 64), p(64, 64), p(64, 0)], [q(1, 2), q(2, 3), q(3, 2), q(4, 0)]),
            (.init(x: 0, y: 0), [p(16, 16), p(32, 32), p(48, 48)], [q(3, 3)]),
            (.init(x: 1, y: 0), [p(32, 48), p(64, 48), p(80, 0)], [q(3, 2), q(5, 0)]),
            (.init(x: 0, y: 0), [p(64, 0), p(0, 64), p(0, 0)], [q(2, 1), q(1, 1), q(1, 2), q(0, 0)]),
            (.init(x: 0, y: 0), [p(40, 51), p(34, 8), p(64, 0)], [q(1, 1), q(2, 1), q(4, 0)])
        ]
        for (start, controls, expected) in fixtures {
            var budget = CubicStroke.Budget()
            let endpoints = try CubicStroke.flatten(from: start, controls: (controls[0], controls[1], controls[2]),
                                                   visible: visible, budget: &budget)
            #expect(endpoints == expected)
            #expect(budget.usedEdges == expected.count)
        }
    }

    @Test func identicalCurveTerminatesEvenWhenItsChordIsZero() throws {
        var budget = CubicStroke.Budget(maxDepth: 0)
        let point = p(0, 0)
        #expect(try CubicStroke.flatten(from: q(0, 0), controls: (point, point, point), visible: visible, budget: &budget) == [q(0, 0)])
        #expect(budget.usedNodes == 1 && budget.usedEdges == 1)
    }

    @Test func collinearBacktrackingKeepsItsExcursionsAndTerminates() throws {
        var budget = CubicStroke.Budget()
        let endpoints = try CubicStroke.flatten(from: q(0, 0), controls: (p(128, 0), p(-64, 0), p(64, 0)),
                                               visible: visible, budget: &budget)
        #expect(endpoints.last == q(4, 0))
        #expect(endpoints.contains(q(3, 0)))
        #expect(endpoints.contains(q(1, 0)))
        #expect(endpoints.count > 1)
        #expect(budget.usedNodes < 100)
    }

    @Test func fractionalEndIsRoundedAndPriorStartIsAnIntegerCosmeticPoint() throws {
        var budget = CubicStroke.Budget()
        let endpoints = try CubicStroke.flatten(from: q(1, 0), controls: (p(24, 0), p(32, 0), p(41, 0)),
                                               visible: visible, budget: &budget)
        #expect(endpoints.last == q(3, 0))
    }

    @Test func nodeEdgeAndDepthBudgetsRejectBeforeReturningAPartialCurve() {
        let controls = (p(0, 64), p(64, 64), p(64, 0))
        var noNodes = CubicStroke.Budget(maxNodes: 0)
        #expect(throws: StrokeError.workLimit) {
            try CubicStroke.flatten(from: q(0, 0), controls: controls, visible: visible, budget: &noNodes)
        }
        var twoEdges = CubicStroke.Budget(maxEdges: 2)
        #expect(throws: StrokeError.workLimit) {
            try CubicStroke.flatten(from: q(0, 0), controls: controls, visible: visible, budget: &twoEdges)
        }
        #expect(twoEdges.usedEdges == 2)
        var zeroDepth = CubicStroke.Budget(maxDepth: 0)
        #expect(throws: StrokeError.workLimit) {
            try CubicStroke.flatten(from: q(0, 0), controls: controls, visible: visible, budget: &zeroDepth)
        }
    }

    @Test func sharedBudgetIsNotResetBetweenCurves() throws {
        var budget = CubicStroke.Budget(maxNodes: 1, maxEdges: 1)
        let controls = (p(16, 0), p(32, 0), p(48, 0))
        #expect(try CubicStroke.flatten(from: q(0, 0), controls: controls, visible: visible, budget: &budget) == [q(3, 0)])
        #expect(throws: StrokeError.workLimit) {
            try CubicStroke.flatten(from: q(0, 0), controls: controls, visible: visible, budget: &budget)
        }
    }

    @Test func conservativeOffscreenPruningKeepsEndpointAndUsesOneNode() throws {
        var budget = CubicStroke.Budget(maxNodes: 1, maxEdges: 1, maxDepth: 0)
        let endpoints = try CubicStroke.flatten(from: q(1000, 1000),
            controls: (p(32_000, 16_000), p(16_000, 32_000), p(32_000, 32_000)), visible: visible, budget: &budget)
        #expect(endpoints == [q(2000, 2000)])
        #expect(budget.usedNodes == 1)
    }

    @Test func extremeFixedCoordinatesAreBoundedWithoutNarrowArithmeticOverflow() throws {
        var budget = CubicStroke.Budget(maxNodes: 100, maxEdges: 100)
        let outside = try CubicStroke.flatten(from: q(134_217_728, 134_217_728),
            controls: (p(.max, .max), p(.max - 16, .max), p(.max, .max - 16)), visible: visible, budget: &budget)
        #expect(outside.last == q(134_217_728, 134_217_727))
        var bounded = CubicStroke.Budget(maxNodes: 10, maxEdges: 10)
        #expect(throws: StrokeError.workLimit) {
            try CubicStroke.flatten(from: q(0, 0), controls: (p(.min, .max), p(.max, .min), p(.max, .max)),
                                    visible: visible, budget: &bounded)
        }
        var validBudget = CubicStroke.Budget()
        #expect(throws: StrokeError.invalidPath) {
            try CubicStroke.flatten(from: q(.max, 0), controls: (p(0, 0), p(0, 0), p(0, 0)),
                                    visible: visible, budget: &validBudget)
        }
    }

    private func p(_ x: Int32, _ y: Int32) -> StrokePoint { .init(x: x, y: y) }
    private func q(_ x: Int32, _ y: Int32) -> Point { .init(x: x, y: y) }
}
